//! Port of captured v+tG, vp1n, dVMb, xt89 with their default Link-modal flags.
//! Fixed patterns are generated by scripts/slack-list-link-oracle.mjs. All
//! matching/indexing uses UTF-16 code units, as the source non-u JS regexes do.
use super::ListError;
use regress::{Match, Regex};
use std::{
    collections::{HashMap, HashSet},
    sync::OnceLock,
};

#[cfg(test)]
mod tests;
mod urls;
mod whole;

struct Patterns {
    regex: HashMap<String, Regex>,
    tlds: HashSet<String>,
    common: HashSet<String>,
    common_max: usize,
    country: HashSet<String>,
    delimiters: Vec<u16>,
}
impl Patterns {
    fn load() -> Result<Self, ListError> {
        let value: serde_json::Value = serde_json::from_str(include_str!("detector/patterns.json"))
            .map_err(|_| ListError("Link matching data is unavailable."))?;
        let mut regex = HashMap::new();
        for (key, value) in value
            .as_object()
            .ok_or(ListError("Link matching data is unavailable."))?
        {
            if let Some(source) = value["source"].as_str() {
                let compiled = Regex::from_unicode(
                    non_unicode_pattern(source).into_iter(),
                    value["flags"].as_str().unwrap_or(""),
                )
                .map_err(|error| {
                    eprintln!("Link fixed pattern {key} could not compile: {error}");
                    ListError("Link matching patterns are unavailable.")
                })?;
                regex.insert(key.clone(), compiled);
            }
        }
        for (key, source) in [
            ("daylite", r"^daylite://Command=ShowObject&\S+"),
            ("hansoft", r"^hansoft://\S+"),
            ("rdar", r"^rdar://[0-9][0-9&]*"),
        ] {
            regex.insert(
                key.into(),
                Regex::new(source)
                    .map_err(|_| ListError("Link matching patterns are unavailable."))?,
            );
        }
        let strings = |key: &str| {
            value[key]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|v| v.as_str().map(str::to_owned))
                .collect()
        };
        let common: HashSet<String> = strings("common_tlds");
        let common_max = common.iter().map(String::len).max().unwrap_or(0).max(3);
        Ok(Self {
            regex,
            tlds: strings("tlds"),
            common,
            common_max,
            country: strings("country_tlds"),
            delimiters: value["delimiters"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|v| v.as_str())
                .flat_map(str::encode_utf16)
                .collect(),
        })
    }
    fn find(&self, key: &str, text: &[u16], start: usize) -> Option<Match> {
        self.regex[key].find_from_ucs2(text, start).next()
    }
    fn test(&self, key: &str, text: &[u16]) -> bool {
        self.find(key, text, 0).is_some()
    }
    fn cjk(&self, c: Option<u16>) -> bool {
        c.is_some_and(|c| self.test("cjk", &[c]))
    }
}

// regress 0.12 combines adjacent escaped surrogate pairs even without `u`.
// JS non-u classes instead see separate code units: [\ud83c\udffb-\udfff].
// Present surrogate escapes as literal u32 code units to its exotic-encoding
// parser. Retain all other escapes, including escaped backslashes, verbatim.
fn non_unicode_pattern(source: &str) -> Vec<u32> {
    let input = source.encode_utf16().collect::<Vec<_>>();
    let mut result = Vec::with_capacity(input.len());
    let mut i = 0;
    while i < input.len() {
        if input[i] == b'\\' as u16 && i + 1 < input.len() {
            if input[i + 1] == b'u' as u16 && i + 5 < input.len() {
                let hex = String::from_utf16(&input[i + 2..i + 6]).ok();
                if let Some(value) = hex
                    .and_then(|s| u16::from_str_radix(&s, 16).ok())
                    .filter(|v| (0xd800..=0xdfff).contains(v))
                {
                    result.push(u32::from(value));
                    i += 6;
                    continue;
                }
            }
            result.push(u32::from(input[i]));
            result.push(u32::from(input[i + 1]));
            i += 2;
        } else {
            result.push(u32::from(input[i]));
            i += 1;
        }
    }
    result
}

#[derive(Clone)]
struct Hit {
    offset: usize,
    text: Vec<u16>,
    url: Vec<u16>,
}
fn text(value: &str) -> Vec<u16> {
    value.encode_utf16().collect()
}
fn string(value: &[u16]) -> Result<String, ListError> {
    String::from_utf16(value)
        .map_err(|_| ListError("This link contains an unsupported split Unicode character."))
}
fn starts(value: &[u16], prefix: &str) -> bool {
    value.starts_with(&text(prefix))
}
fn contains(value: &[u16], needle: &str) -> bool {
    let n = text(needle);
    value.windows(n.len()).any(|v| v == n)
}
fn index(value: &[u16], needle: &str) -> Option<usize> {
    let n = text(needle);
    value.windows(n.len()).position(|v| v == n)
}
fn group<'a>(m: &Match, input: &'a [u16], i: usize) -> Option<&'a [u16]> {
    m.group(i).map(|r| &input[r])
}
fn truthy(value: Option<&[u16]>) -> bool {
    value.is_some_and(|v| !v.is_empty())
}
fn js_space(c: char) -> bool {
    matches!(c,'\u{0009}'..='\u{000d}'|'\u{0020}'|'\u{00a0}'|'\u{1680}'|'\u{2000}'..='\u{200a}'|'\u{2028}'|'\u{2029}'|'\u{202f}'|'\u{205f}'|'\u{3000}'|'\u{feff}')
}

pub(super) fn normalize(input: &str) -> Result<String, ListError> {
    let p = whole::patterns()?;
    let input_text = text(input.trim_matches(js_space));
    let mut hits = urls::detect(p, &input_text)?;
    merge(&mut hits, emails(p, &input_text));
    merge(&mut hits, phones(p, &input_text));
    hits.sort_by_key(|hit| hit.offset);
    hits.first()
        .map_or_else(|| Ok(input.to_owned()), |hit| string(&hit.url))
}
fn merge(current: &mut Vec<Hit>, next: Vec<Hit>) {
    // Source mergeMatches checks only the already accepted URL/email family,
    // not its incoming siblings. Preserve order for stable offset ties.
    let accepted = next
        .into_iter()
        .filter(|candidate| {
            !current.iter().any(|old| {
                let (a, b) = (candidate.offset, candidate.offset + candidate.text.len());
                let (c, d) = (old.offset, old.offset + old.text.len());
                a == c || b == d || (a <= c && b >= d) || (a >= c && a < d) || (b >= c && b < d)
            })
        })
        .collect::<Vec<_>>();
    current.extend(accepted);
}
fn emails(p: &Patterns, input: &[u16]) -> Vec<Hit> {
    let mut hits = Vec::new();
    for m in p.regex["email"].find_from_ucs2(input, 0) {
        let mut value = input[m.range()].to_vec();
        if let Some(end) = group(&m, input, 4).filter(|v| !v.is_empty()) {
            value.truncate(value.len() - end.len());
        }
        let tld = group(&m, input, 3)
            .and_then(|v| string(v).ok())
            .unwrap_or_default()
            .to_ascii_lowercase();
        if value.len() > 254 || !p.tlds.contains(&tld) {
            continue;
        }
        let mut offset = m.start();
        if value.first().is_some_and(|c| p.delimiters.contains(c)) {
            value.remove(0);
            offset += 1;
        }
        let mut url = text("mailto:");
        url.extend_from_slice(&value);
        if offset.checked_sub(1).and_then(|i| input.get(i)) == Some(&(b'@' as u16))
            || (starts(&url, "mailto:git@")
                && input.get(offset + value.len()) == Some(&(b':' as u16)))
        {
            continue;
        }
        hits.push(Hit {
            offset,
            text: value,
            url,
        });
    }
    hits
}
fn phones(p: &Patterns, input: &[u16]) -> Vec<Hit> {
    let mut hits = Vec::new();
    for m in p.regex["phone"].find_from_ucs2(input, 0) {
        let original = &input[m.range()];
        if original
            .iter()
            .all(|c| (*c >= b'0' as u16) && (*c <= b'9' as u16))
        {
            continue;
        }
        let mut value = original.to_vec();
        let mut offset = m.start();
        if starts(&value, "(") && !contains(&value, ")") {
            value.remove(0);
            offset += 1;
        }
        let plus = truthy(group(&m, input, 1)) || truthy(group(&m, input, 2));
        let mut url = text(if plus { "tel:+" } else { "tel:" });
        url.extend(
            original
                .iter()
                .copied()
                .filter(|c| (*c >= b'0' as u16) && (*c <= b'9' as u16)),
        );
        let before = offset.checked_sub(1).and_then(|i| input.get(i)).copied();
        let end = offset + value.len();
        let after = input.get(end).copied();
        let left = offset == 0
            || before.is_some_and(|c| text(" \u{3000}\n([{'\"").contains(&c))
            || p.cjk(before);
        let right = end == input.len()
            || after.is_some_and(|c| text(" \u{3000}\n.)]}'\":?!;,").contains(&c))
            || p.cjk(after);
        if left && right {
            hits.push(Hit {
                offset,
                text: value,
                url,
            });
        }
    }
    hits
}
